-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
-- An incremental model: built in full the first time, then only rows past the watermark.
CREATE TABLE IF NOT EXISTS intermediate.hub_order AS
-- A Data Vault hub: insert-only. Each hub_order_hk is added once, the first time it is loaded.

with orders as (

    select * from staging.stg_tpch_erp__orders

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(orders.o_orderkey AS BIGINT) AS TEXT))), '')) as hub_order_hk,
        cast(orders.o_orderkey as BIGINT) as order_number,
        cast(orders._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from orders

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_order_hk
            order by incoming.load_date asc
        ) as row_in_batch
    from incoming

)

select
    ranked.hub_order_hk,
    ranked.order_number,
    ranked.load_date,
    ranked.record_source
from ranked

where ranked.row_in_batch = 1;
-- The rows past the watermark, kept aside while the old versions of them are removed.
DROP TABLE IF EXISTS hub_order__new;
CREATE TEMPORARY TABLE hub_order__new AS
-- A Data Vault hub: insert-only. Each hub_order_hk is added once, the first time it is loaded.

with orders as (

    select * from staging.stg_tpch_erp__orders

),

incoming as (

    select
        MD5(COALESCE(UPPER(TRIM(CAST(CAST(orders.o_orderkey AS BIGINT) AS TEXT))), '')) as hub_order_hk,
        cast(orders.o_orderkey as BIGINT) as order_number,
        cast(orders._ingested_at as TIMESTAMPTZ) as load_date,
        'tpch_erp' as record_source
    from orders

    where cast(orders._ingested_at as TIMESTAMPTZ) > (select coalesce(max(load_date), cast('1900-01-01' as TIMESTAMPTZ)) from intermediate.hub_order)

),

ranked as (

    select
        incoming.*,
        row_number() over (
            partition by incoming.hub_order_hk
            order by incoming.load_date asc
        ) as row_in_batch
    from incoming

)
,

latest as (

    select hub_order_hk
    from (
        select
            existing.hub_order_hk,
            row_number() over (partition by existing.hub_order_hk order by existing.load_date desc) as row_in_table
        from intermediate.hub_order as existing
    ) as versions
    where row_in_table = 1

)

select
    ranked.hub_order_hk,
    ranked.order_number,
    ranked.load_date,
    ranked.record_source
from ranked

left join latest
    on latest.hub_order_hk = ranked.hub_order_hk

where ranked.row_in_batch = 1

    and latest.hub_order_hk is null;
INSERT INTO intermediate.hub_order (hub_order_hk, order_number, load_date, record_source)
SELECT hub_order_hk, order_number, load_date, record_source FROM hub_order__new;
DROP TABLE hub_order__new;
